# Glossary of meeting 2: every term in plain words and in professional wording, with an example from the bistro and a caution.
T('dmodel', 'מודל נתונים', 'Data Model', 'התוכנית של מה שהמערכת זוכרת: אילו טבלאות, אילו עמודות, מה מותר בכל עמודה, ואיך הטבלאות מחוברות.', 'ייצוג מובנה של הנתונים בארגון, של הכללים החלים עליהם ושל הקשרים ביניהם, המשמש בסיס לתכנון מסד הנתונים.', 'שש הטבלאות של הביסטרו, עם המזהים, המפתחות והקשרים ביניהן.', 'מודל נתונים נבנה מההחלטה ומהדרישות אחורה, ולא מרשימה של כל מה שאפשר לרשום.')
T('levels', 'שלוש רמות של מודל', 'Conceptual, Logical, Physical', 'אותו מודל בשלוש רמות פירוט: מושגי (מה הלקוח מתאר), לוגי (טבלאות, עמודות ומפתחות), פיזי (פקודות שרצות במסד מסוים).', 'הבחנה בין מודל מושגי, מודל לוגי ומודל פיזי, לפי מידת התלות בטכנולוגיה ובפרטי המימוש.', 'מושגי: הזמנה, מנה, מלצר, שולחן. לוגי: התרשים. פיזי: `bistro.sql`.', 'קל לשנות ברמה המושגית והלוגית. שינוי ברמה הפיזית, אחרי שהמסד מלא, יקר בהרבה.')
T('schema', 'הגדרת טבלה', 'Schema', 'צד ההגדרה של הטבלה: שמות העמודות, הסוגים והכללים. נקבעת פעם אחת, וחלה על כל שורה.', 'מבנה הטבלה כפי שהוא מוגדר במסד הנתונים: עמודות, טיפוסי נתונים, אילוצים ומפתחות.', 'בטבלת המנות: dish_id מספר שלם, name טקסט, price עשרוני, available כן או לא.', 'מי שמאפיין קובע את ההגדרה. את התוכן ממלא התהליך.')
T('record', 'רשומה ושדה', 'Record, Field', 'רשומה היא שורה: פריט אחד עם כל הפרטים שלו. שדה הוא עמודה: פרט אחד שנשמר על כל פריט.', 'רשומה היא מופע יחיד של הישות בטבלה. שדה הוא תכונה של הישות, המוגדרת כעמודה.', 'השורה של הסלט היא רשומה. price הוא שדה.', 'בכל תא ערך אחד בלבד. תא שמחזיק רשימה הוא סימן שחסרה טבלה.')
T('anom', 'תקלות עדכון, הוספה ומחיקה', 'Update, Insert and Delete Anomalies', 'שלוש תקלות של טבלה שבה עובדות על נושאים שונים גרות באותה שורה: עובדה עם שתי גרסאות, עובדה שאין איפה לרשום, ועובדה שנמחקת בטעות.', 'חריגות הנובעות מכפילות נתונים בטבלה שאינה מנורמלת, ופוגעות בעקביות הנתונים בעת עדכון, הוספה או מחיקה.', 'ליוסי שני מספרי טלפון. אין איפה לרשום שקשוקה. ביטול הזמנה מחק את הטלפון של עומר.', 'אלה אינן טעויות של מי שמקליד. הן תוצאה של המבנה, ולכן מתקנים את המבנה.')
T('norm', 'נרמול', 'Normalization', 'סידור הנתונים בטבלאות כך שכל עובדה כתובה פעם אחת, במקום אחד, ובכל מקום אחר רק מצביעים עליה.', 'תהליך פירוק טבלאות לטבלאות קטנות יותר, כך שכל תכונה תלויה במפתח של הטבלה שלה בלבד, ונמנעת כפילות של עובדות.', 'הטלפון של יוסי בטבלת המלצרים. ההזמנה מחזיקה רק את המספר 17.', 'השאלה שעושה כמעט את כל העבודה: על כל עמודה, ״על מה העובדה הזאת?״.')
T('dtype', 'סוג נתונים', 'Data Type', 'הגדרה של איזה ערך מותר בעמודה: טקסט, מספר שלם, עשרוני, תאריך ושעה, או כן ולא.', 'טיפוס הנתונים של עמודה, הקובע את טווח הערכים המותר ואת הפעולות שאפשר לבצע עליהם.', '`price DECIMAL(8,2)`: אפשר לחבר ולמיין מחירים.', 'ספרות שלא מחשבים איתן, כמו טלפון ותעודת זהות, הן טקסט.')
T('constr', 'אילוץ', 'Constraint', 'כלל שמוגדר על עמודה, והמסד אוכף אותו בעצמו: שורה שמפרה את הכלל אינה נשמרת.', 'תנאי הצהרתי על ערכי עמודה או טבלה (NOT NULL, UNIQUE, CHECK, DEFAULT, מפתחות), שמערכת ניהול מסד הנתונים מבטיחה את קיומו.', '`CHECK (price > 0)`: קפה במחיר 0 נדחה ברגע ההקלדה.', 'דרישה טובה הופכת לאילוץ. אילוץ שנשכח הופך לבקשה מהעובדים ״להקפיד״.')
T('pk', 'מזהה ראשי', 'Primary Key', 'העמודה שמבדילה כל שורה בטבלה מכל שורה אחרת: ייחודית, תמיד קיימת, ואינה משתנה.', 'עמודה, או צירוף עמודות, שערכה מזהה באופן חד ערכי כל רשומה בטבלה ואינו ריק.', 'waiter_id בטבלת המלצרים: 17 הוא יוסי של הערב, ורק הוא.', 'שם, טלפון ותעודת זהות אינם מזהה טוב: הם חוזרים, משתנים או רגישים.')
T('surr', 'מזהה טבעי ומזהה מלאכותי', 'Natural Key, Surrogate Key', 'מזהה טבעי הוא פרט מהעולם שנראה ייחודי. מזהה מלאכותי הוא מספר שהמערכת נותנת רק כדי לזהות.', 'מפתח טבעי נגזר מתכונות הישות. מפתח חלופי (מלאכותי) הוא ערך שהמערכת מייצרת ואין לו משמעות עסקית.', 'הטלפון של יוסי הוא מזהה טבעי. המספר 17 הוא מזהה מלאכותי.', 'מזהה מלאכותי אינו משתנה כשהעולם משתנה, ולכן ההפניות אליו אינן נשברות.')
T('fk', 'מפתח זר', 'Foreign Key', 'עמודה בטבלה אחת שמחזיקה את המזהה הראשי של שורה בטבלה אחרת. כך שורה ״מצביעה״ על שורה.', 'עמודה שערכיה חייבים להופיע כערכי מפתח ראשי בטבלה המוזכרת, ומממשת את הקשר בין הטבלאות.', '`FOREIGN KEY (waiter_id) REFERENCES waiters(waiter_id)`', 'עוזרים, כלים ואנשים נוטים לשכוח את שורת ה-FOREIGN KEY. בודקים שהיא קיימת.')
T('refint', 'שלמות הפניות', 'Referential Integrity', 'כל מפתח זר מצביע על שורה שקיימת באמת.', 'כלל המבטיח שלכל ערך של מפתח זר קיים ערך תואם במפתח הראשי של הטבלה המוזכרת.', 'הזמנה עם מלצר 44, שאינו קיים, נדחית: FOREIGN KEY constraint failed.', 'את מה שיש לו היסטוריה מסמנים כלא פעיל, ולא מוחקים.')
T('rel', 'קשר וסוגיו', 'Relationship, Cardinality', 'האופן שבו שורות בשתי טבלאות קשורות: לשורה אחת כאן, כמה שורות שם? אחד לאחד, אחד לרבים, או רבים לרבים.', 'קשר בין ישויות וריבוי (Cardinality) שלו, הנקבע לפי מספר המופעים האפשרי בכל צד.', 'מלצר והזמנות: אחד לרבים. הזמנות ומנות: רבים לרבים.', 'שואלים בשני הכיוונים. ואת התשובות נותן התהליך, לא הטבלאות.')
T('crow', 'רגל עורב', 'Crow\'s Foot', 'סימון בקצה קו בתרשים: שלוש שורות נפתחות הן ״רבים״, שני קווים קצרים הם ״אחד בדיוק״.', 'סימון ריבוי בתרשימי ישויות וקשרים, שבו המזלג מציין ״רבים״ והקו הניצב מציין ״אחד״.', 'רגל העורב ליד orders: למלצר אחד הרבה הזמנות.', 'המפתח הזר יושב תמיד בצד של רגל העורב.')
T('junc', 'טבלת קישור', 'Junction Table', 'טבלה שכל שורה בה מחברת שורה אחת מטבלה אחת לשורה אחת מטבלה אחרת, כמו שורה בחשבונית.', 'טבלה מקשרת הממשת קשר רבים לרבים כשני קשרים של אחד לרבים, ומחזיקה את התכונות של הצירוף.', 'order_items: מנה אחת בהזמנה אחת, עם כמות, הערה ומחיר ששולם.', 'עמודות ממוספרות (מנה 1, מנה 2) או ״עד שני סוגים״ הן סימן שחסרה טבלת קישור.')
T('erd', 'תרשים ישויות וקשרים', 'Entity Relationship Diagram, ERD', 'ציור של מודל הנתונים: מלבן לכל טבלה, קו לכל קשר, וסימון ״אחד״ או ״רבים״ בכל קצה.', 'ייצוג גרפי של ישויות, תכונותיהן והקשרים ביניהן, המשמש לתכנון ולתקשורת בין בעלי העניין.', 'התרשים של הביסטרו: שש טבלאות וחמישה קשרים.', 'תרשים יפה אינו תרשים נכון. בודקים שלהחלטה ולכל דרישה יש מסלול בתרשים.')
T('assume', 'הנחת מודל', 'Modeling Assumption', 'החלטה מתועדת על מה שהמודל אינו מכסה, ולמה.', 'הנחה מפורשת בתיעוד המודל, המגדירה את גבולותיו ואת המקרים שאינם נתמכים בו.', '״הזמנה רשומה על המלצר שפתח אותה, גם כששני מלצרים משרתים את השולחן.״', 'מה שלא תועד ייראה בעוד שנה כמו טעות שנשכחה.')
T('dict', 'מילון נתונים', 'Data Dictionary', 'טבלה שמתעדת כל עמודה במודל: באיזו טבלה היא, מה הסוג, מה הכלל, ולמה היא קיימת.', 'מאגר מטא-נתונים המתאר את מבנה הנתונים, משמעותם, הכללים החלים עליהם ומקורם.', 'price_paid: עשרוני, חובה, כדי שחשבון ישן לא ישתנה כשהמחיר עולה.', 'עמודה שאי אפשר לכתוב לה ״למה היא קיימת״ היא מועמדת למחיקה.')
T('sql', 'SQL', 'Structured Query Language', 'השפה שבה מגדירים טבלאות, מוסיפים ומשנים שורות, ושואלים את מסד הנתונים.', 'שפה הצהרתית סטנדרטית לניהול מסדי נתונים יחסיים, להגדרת מבנים ולטיפול בנתונים.', '`SELECT name, price FROM dishes ORDER BY price DESC;`', 'אין צורך לשנן תחביר. צריך לדעת לקרוא שורה ולהבין מה היא עושה ולמה.')
T('ddl', 'פקודות שמגדירות מבנה', 'Data Definition Language, DDL', 'פקודות שיוצרות, משנות או מוחקות טבלה: `CREATE TABLE`, `ALTER TABLE`, `DROP TABLE`.', 'תת-שפה של SQL להגדרת מבני הנתונים ולשינויים בהם.', '`ALTER TABLE dishes ADD COLUMN supplier_id INTEGER`', '`DROP TABLE` מוחקת טבלה עם כל השורות שבה. מחייבת גיבוי ואישור.')
T('dml', 'פקודות שעובדות עם שורות', 'Data Manipulation Language, DML', 'פקודות שמוסיפות, משנות, מוחקות או שואלות שורות: `INSERT`, `UPDATE`, `DELETE`, `SELECT`.', 'תת-שפה של SQL לטיפול בנתונים השמורים בטבלאות.', '`UPDATE waiters SET active = FALSE WHERE waiter_id = 31;`', 'כל אירוע בתהליך מפעיל פקודה. מלצר שעוזב הוא `UPDATE`, לא `DELETE`.')
T('join', 'צירוף טבלאות', 'JOIN', 'שאילתה שמחברת שורות משתי טבלאות לפי מפתח זר, ומחזירה אותן יחד.', 'פעולת צירוף המשלבת רשומות מטבלאות שונות לפי תנאי התאמה, בדרך כלל בין מפתח זר למפתח ראשי.', 'החשבונית של 1201 נבנית משורות ההזמנה ומטבלת המנות.', 'דוח שמשלב שתי טבלאות אפשרי רק אם יש מפתח זר שמחבר ביניהן.')
GL_LESSON = ['dmodel', 'levels', 'schema', 'record', 'anom', 'norm', 'dtype', 'constr', 'pk', 'surr', 'fk', 'refint', 'rel', 'crow', 'junc', 'erd', 'assume', 'dict', 'sql', 'ddl', 'dml', 'join']
